  SIITS.NEWS=[
    {id:"n-20261113-wazir",t:"انتهاء اجتماع المكتب الوطني مع السيد وزير الصحة والحماية الاجتماعية",c:"المكتب الوطني",d:"في إطار الحوار الاجتماعي القطاعي ومواصلة الترافع عن الملف المطلبي للممرضين وتقنيي الصحة، انتهى قبل قليل الاجتماع الذي عقده المكتب الوطني للنقابة المستقلة للممرضين وتقنيي الصحة مع السيد وزير الصحة والحماية الاجتماعية.\n\nوقد شكّل هذا اللقاء مناسبة لطرح أبرز القضايا التي تشغل الشغيلة التمريضية، وفي مقدمتها صون المكتسبات وتحصين الهوية التمريضية.\n\nسنوافيكم بالتفاصيل فيما بعد.\n\nلنواصل المسار.",date:"2026-11-13",r:"وطني",src:"المكتب الوطني",url:"",img:"images/news/wazir-ijtimaa-2026-11-13.jpg"},
    {t:"سوس ماسة: لقاء المكتبين الجامعيين للنقابتين المستقلتين مع مدير المجموعة الصحية الترابية في الجلسة الثانية للحوار الاجتماعي",c:"أنشطة",d:"في سياق الجلسة الثانية من جلسات الحوار الاجتماعي، عقد كل من المكتب الجامعي للنقابة المستقلة للأطر الإدارية والتقنية ومساعدي الصحة والمكتب الجامعي للنقابة المستقلة للممرضين وتقنيي الصحة لقاءً مع السيد مدير المجموعة الصحية الترابية سوس ماسة.\n\nوقد شكّل هذا اللقاء مناسبة لنقاش مثمر وحوار غني ومستفيض انصبّ على مختلف القضايا والملفات المطلبية، في أجواء اتسمت بالجدية وتبادل وجهات النظر واستحضار المسؤولية المشتركة في معالجة الإشكالات المطروحة.\n\nوإذ نثمّن هذه الخطوة الإيجابية، فإننا نعتبرها لبنة أساسية في مسار إرساء حوار اجتماعي مؤسساتي جاد ومنتج، قوامه الإنصات المتبادل والاعتراف بمشروعية المطالب والوضوح في المواقف والالتزامات، بما يفتح آفاقاً حقيقية لمعالجة الملفات العالقة وصون كرامة الأطر الإدارية والتقنية والتمريضية ومساعدي الصحة.\n\nإننا نؤمن بأن قيمة الحوار لا تقاس بمجرد انعقاده، وإنما بما يؤسس له من ثقة ووضوح، وما يفضي إليه من التزامات، وما يحققه من أثر ملموس على أرض الواقع. فالحوار المسؤول ليس بديلاً عن المطالبة بالحقوق، بل هو أحد المسارات الجادة لإنصاف أصحابها.\n\nوفي انتظار إصدار بلاغ تفصيلي يستعرض مختلف محاور النقاش والملفات المطروحة ومخرجات هذا اللقاء، نثمّن كل خطوة تفتح أبواب الحوار، ونراهن على أن تتحول إرادة التواصل إلى إرادة فعل، وأن تنتقل الالتزامات من محاضر الاجتماعات إلى واقع الممارسة.\n\nونواصل المسار 🇲🇦",date:"2026-11-12",r:"أكادير",src:"المكتب الجامعي - سوس ماسة",url:"",img:"images/news/souss-ggt-hiwar-2026-11-12.jpg"},
    {id:"n-20261112-1url9",t:"مكتب التنسيق الوطني للوكالة المغربية للدم ومشتقاته يعقد اجتماعاً مطوّلاً مع إدارة الوكالة بحضور الكاتب الوطني",c:"أنشطة",d:"عقد مكتب التنسيق الوطني للوكالة المغربية للدم ومشتقاته، التابع للنقابة المستقلة للممرضين وتقنيي الصحة، اجتماعاً مطوّلاً مع إدارة الوكالة المغربية للدم ومشتقاته، وذلك بحضور السيد الكاتب الوطني وتمثيلية عن المكتب الوطني.\n\nواتسم الاجتماع بروح الجدية والمسؤولية والاستعداد المتبادل للمضي قدماً بهذه المؤسسة الاستراتيجية.\n\nيستمر الترافع والدفاع عن الهوية التمريضية.\n\nباقي التفاصيل لاحقاً.",date:"2026-11-12",r:"وطني",src:"النقابة المستقلة للممرضين وتقنيي الصحة",url:"",img:"images/news/amsd-ijtimaa-2026-11-12.jpg"},
    {t:"طنجة: المكتب الجهوي لجهة طنجة تطوان الحسيمة ينظم المؤتمر الجهوي الثاني يوم السبت 21 نونبر",c:"تنظيم",d:"في إطار الدينامية وتجديد النخب، ومواصلة المسار النضالي والترافعي، ينظم المكتب الجهوي للنقابة المستقلة للممرضين وتقنيي الصحة بجهة طنجة تطوان الحسيمة المؤتمر الجهوي الثاني تحت شعار:\n\n«لا نجاح لأي إصلاح إلا بتحصين المكتسبات والتحفيز الفعلي لأسرة التمريض»\n\n📅 يوم السبت 21 نونبر 2026\n🕙 على الساعة العاشرة صباحاً (10:00)\n📍 المعهد العالي للمهن التمريضية وتقنيات الصحة بطنجة\n\nوعليه، نرحب بكافة المؤتمرات والمؤتمرين مناضلي النقابة المستقلة للممرضين وتقنيي الصحة بالجهة.\n\nالنقابة المستقلة للممرضين وتقنيي الصحة بجهة طنجة تطوان الحسيمة: دينامية تنظيمية حقيقية وترافع قوي، مسؤول ومستمر. فعاشت حرة مناضلة أبية 💚✌️",date:"2026-11-12",r:"طنجة",src:"المكتب الجهوي بجهة طنجة تطوان الحسيمة",url:"",img:"images/news/tanger-congres2-2026-11-21.jpg"},
    {t:"ورزازات: 21 التزاماً بعد 8 ساعات من الحوار مع اللجنة الجهوية، أبرزها صرف تعويضات الحراسة بصيغة النقابة",c:"مستجدات مهنية",d:"إلى عموم الشغيلة الصحية والإدارية والتقنية ومساعدي الصحة، وإلى الرأي العام المحلي والإقليمي والجهوي.\n\nعلى إثر البيان الإنذاري المشترك الصادر بتاريخ 4 نونبر 2026، الذي دق من خلاله التنسيق النقابي ناقوس الخطر بشأن جملة من الاختلالات الإدارية والتدبيرية والتنظيمية بمستشفى سيدي حساين بناصر ومستشفى التخصصات بوكافر بورزازات، انعقد يوم الأربعاء 11 نونبر 2026 اجتماع مع اللجنة الجهوية للحوار الاجتماعي، بحضور ممثلين عن المديرية الجهوية للصحة والحماية الاجتماعية، بمقر المندوبية الإقليمية للصحة والحماية الاجتماعية بورزازات.\n\nوجاء هذا الاجتماع تتويجاً لمسار من الترافع النقابي والتواصل والمراسلات، واستجابة لمطالب البيان الإنذاري المشترك. وامتدت أشغاله لأكثر من 8 ساعات إلى حدود منتصف الليل، في نقاش مستفيض ومسؤول أسفر عن مجموعة من الالتزامات، أهمها:\n\n1) التعجيل بصرف التعويضات عن الحراسة والإلزامية والمداومة إلى حدود 30 شتنبر 2026، بعد استكمال مرحلة الالتزام، داخل أجل أقصاه 20 يوماً من تاريخ توقيع المحضر.\n2) اعتماد صيغة الاحتساب التي تقدمت بها ودافعت عنها النقابة المستقلة للممرضين وتقنيي الصحة، بما يتيح شمول هذه التعويضات مستحقات الثلث الثالث من سنة 2026، خلافاً لإعلان الإدارة الذي اقتصر على النصف الثاني من 2025 والنصف الأول من 2026.\n3) تفعيل جميع مقررات انتقال المساعدين في العلاج.\n4) تسوية وضعية الأطر الحاصلة على مذكرات مصلحة مؤقتة.\n5) تطبيق القانون وضمان مبدأ المساواة بين جميع الأطر الصحية والإدارية.\n6) تيسير استفادة الأطر الصحية وذويهم من الخدمات الصحية بالمركز الاستشفائي الإقليمي سيدي حساين بناصر.\n7) تفعيل التكوين المستمر للأطر الصحية والإدارية.\n8) تفعيل الدورية الوزارية رقم 11 الخاصة بالحوار الاجتماعي، والتجاوب مع المشاكل المستعجلة.\n9) تنظيم العمل الإداري بإصدار مذكرة مصلحة، وضبط مسار المراسلات والطلبات عبر مكتب الضبط.\n10) السكن الوظيفي: التذكير بالاتفاق مع المندوب الإقليمي على تخصيص خمس وحدات سكنية للأطر التمريضية والتقنية والإدارية ومساعدي الصحة وفق معايير الاستحقاق.\n11) احترام التسلسل الإداري والاختصاصات طبقاً للنظام الداخلي للمؤسسة، خاصة في تدبير الموارد البشرية والتداريب الاستشفائية والأدوية والمستلزمات الطبية.\n12) إحداث مصلحة المساعدة الطبية المستعجلة SAMU، مع توفير التجهيزات وتكوين الأطر المعنية وتحفيزها.\n13) إحداث مجلس للممرضين، بناءً على مراسلة رسمية تقدمت بها النقابة المستقلة للممرضين وتقنيي الصحة.\n14) تعزيز مستشفى التخصصات بوكافر بالموارد البشرية الصحية والإدارية الكافية.\n15) تحسين ظروف اشتغال الممرضين بمصلحة المستعجلات.\n16) تحسين خدمات المطبخ والتغذية عبر لجنة مختصة.\n17) تفعيل لجنة المراقبة والتتبع الخاصة بشركات المناولة.\n18) معالجة إشكالات تدبير الأجهزة والمعدات الطبية عبر اجتماع يضم مختلف المتدخلين.\n19) ضمان استمرارية تزويد المصالح بالأدوية والمستلزمات الطبية.\n20) إحداث مقر جديد لمصلحة المختبر.\n21) احترام الجدولة الزمنية للتداريب الاستشفائية وإعطاء الأولوية لطلبة المعهد العالي للمهن التمريضية وتقنيات الصحة بورزازات، والقطع مع انتحال الصفة ومزاولة المهام خارج الإطار القانوني.\n\nوإذ يثمن التنسيق النقابي ما أفضى إليه هذا الاجتماع من تجاوب مع عدد من المطالب، فإنه يؤكد أن هذه النتائج ثمرة للمواقف النقابية المسؤولة والترافع المستمر، وأن عدداً من الملفات لا يزال يتطلب إجراءات عملية وحسماً نهائياً، خاصة احترام الاختصاصات، وضمان استقلالية القرار الإداري، وحماية الأطر من مختلف أشكال الضغط.\n\nويؤكد التنسيق أن الدفاع عن الحقوق المهنية والاجتماعية للشغيلة الصحية ليس منفصلاً عن الدفاع عن حق المواطن في العلاج، وأن توقيع محضر الاتفاق خطوة أولى، والمعيار الحقيقي لنجاح الحوار هو التنزيل الفعلي للالتزامات داخل الآجال المحددة، دون أن يشكل ذلك تنازلاً عن المطالب المشروعة أو اعتباراً لكل الملفات مسواة نهائياً.\n\nكرامة مهنيي الصحة، وتحسين ظروف اشتغالهم، مدخل أساسي لصون حق المواطن في العلاج والارتقاء بجودة الخدمات الصحية.",date:"2026-11-11",r:"ورزازات",src:"التنسيق النقابي بورزازات (SIITS - SICATAS)",url:"",img:["images/news/ouarzazate-hiwar-2026-11-11.jpg", "images/news/ouarzazate-hiwar-2026-11-11-p1.jpg", "images/news/ouarzazate-hiwar-2026-11-11-p2.jpg", "images/news/ouarzazate-hiwar-2026-11-11-p3.jpg", "images/news/ouarzazate-hiwar-2026-11-11-p4.jpg", "images/news/ouarzazate-hiwar-2026-11-11-p5.jpg", "images/news/ouarzazate-hiwar-2026-11-11-p6.jpg"]},
    {t:"ورزازات: التنسيق النقابي ينظم وقفة احتجاجية أمام مستشفى سيدي حساين بناصر يوم الخميس 12 نونبر",c:"وقفة احتجاجية",d:"يعلن التنسيق النقابي بورزازات، المكوّن من النقابة المستقلة للممرضين وتقنيي الصحة والنقابة المستقلة للأطر الإدارية والتقنية ومساعدي الصحة، عن تنظيم وقفة احتجاجية دفاعاً عن كرامة الشغيلة الصحية وصون حقوقها، والتصدي للاختلالات التدبيرية والإدارية.\n\n📅 الخميس 12 نونبر 2026\n🕥 على الساعة 10:30 صباحاً\n📍 أمام مستشفى سيدي حساين بناصر بورزازات\n\nمطالبنا المشروعة:\n• إدارة جيدة ومستشفى بموارد كافية\n• وقف التسيير العشوائي والظلم الإداري\n• صرف المستحقات والتعويضات في وقتها\n• تحسين ظروف العمل وحماية الأطر الصحية\n• الاستجابة لمطالب الشغيلة الصحية\n• التصدي للاختلالات في المستشفيات\n• العدالة والمساواة في تدبير الموارد البشرية\n\nمعاً من أجل قطاع صحي قوي ومُنصف. حضوركم دعم لنضالنا المشروع.\n\nمستشفى لا يحترم أطره… هو مستشفى لا يحترم مرضاه.\n\n#قضايا_ورزازات",date:"2026-11-11",r:"ورزازات",src:"التنسيق النقابي بورزازات",img:"images/news/ouarzazate-wakfa-2026-11-12.jpg"},
    {t:"في علاقة الإدارة بالنقابة… مقال للأخ عبد اللطيف أهنوش",c:"مقال رأي",d:"بقلم: عبد اللطيف أهنوش، عضو المكتب الوطني والكاتب الجهوي للنقابة بجهة بني ملال خنيفرة\n\nالعلاقة بين الإدارة والنقابة يسمّيها الكثير من الموظفين والكثير من المسؤولين علاقة شراكة، حيث نسمّي النقابة بالشريك الاجتماعي كلما أُريد تلميع شيء بنوع من المشاركة والتفاعل والاستماع والترافع... وهو أمر يمكن تقبّله لو كانت الوزارات والإدارات تعتبر النقابة فعلاً شريكاً حقيقياً وتُشركه في كل شيء...\n\nلكن واقع الحال يقول إن النقابة عليها دائماً أن تذكّر بدورها في المشاركة والمشاورة وأن تُبدي الرغبة، إما عن طريق الاحتجاج أو التعبير... أما الوزارة فلا تبادر إلى استدعاء النقابات إلا لسببين لا ثالث لهما: إما أنها لمست أن القطاع يغلي وأن الاحتجاج قائم أو قادم، أي استدعاء تحت الضغط لإطفاء الغليان، أو استدعاء من أجل إضفاء الشرعية على قرارات أتتها من فوق ولا تعلم عنها شيئاً...\n\nوهذه أمور كلها قد نغضّ عنها البصر إن اعتبرنا النقابة نقابةً لها أهداف، على رأسها الدفاع عن منخرطيها والفئات التي تمثلها، والوزارة وزارةً دورها المركزي السهر على توفير ظروف العمل للشغيلة الصحية لتقديم خدمات للمواطن الذي لا يحضر لطاولات الحوار... ولكن لكي نغضّ البصر عمّا سبق يجب أن نتساءل: ما الغاية من الحوار والاحتجاج والترافع والشراكة والتدافع؟ إنها الوصول إلى اتفاق يُلزم الجميع...\n\nهذا الاتفاق يقودنا إلى أسئلة جوهرية: ما الذي يفرض على الوزارة الالتزام باتفاقاتها؟! بصيغة أخرى، ما الذي يضمن للنقابات أن الاتفاقات الموقّعة مُلزمة للطرف الإداري ما دام هو صاحب التوقيع وصاحب السلطة؟! وهل سبق للمركزيات النقابية أن ترافعت في مجلس المستشارين حول هذا الأمر، كونه مهماً ويحفظ للنقابة هيبتها وكرامتها؟\n\nأطرح هذه الأسئلة لأنه، في ظل التماطل الذي تنهجه الوزارة في تنزيل التزاماتها، لم يعد هناك معنى للشراكة ولا للحوار، وعليها أن تعيد النظر في ذلك... كما علينا كفاعلين إعادة النظر في التعامل مع الوزارة...\n\nأما مركزية المناصب المالية ومركزية الأجور، فجوابنا للسيد الوزير، ما دمت تطلّ علينا من باب الطمأنة، وما دام الأمر بالنسبة لكم لا مساس فيه وبالنسبة لنا غير مطمئن: فلتجد حلاً يُغنينا عن طمأنتك كل سنة.\n\nالصورة من اتفاق 23 يوليوز 2024.",date:"2026-11-11",r:"وطني",src:"عبد اللطيف أهنوش",img:["images/news/ahannouch-2026-11-11.jpg","images/news/ahannouch-idara-naqaba-2026-11-11.jpg"]},
    {t:"بلاغ المجلس الوطني: التشبث باتفاق 23 يوليوز ومركزية المناصب المالية والأجور والاستعداد لمعركة نضالية",c:"المكتب الوطني",d:"في محطة تنظيمية ونضالية هامة، انعقدت الدورة السابعة للمجلس الوطني للنقابة المستقلة للممرضين وتقنيي الصحة منذ التأسيس، والأولى بعد المؤتمر الوطني الثاني، يوم 07 نونبر 2026 بالدار البيضاء، تحت شعار: «الهوية التمريضية: فكر، بناء ونضال»، بحضور أزيد من 100 عضو يمثلون مختلف المكاتب الجهوية والإقليمية والجامعية.\n\nمحطة لتقييم المرحلة، وتوحيد الرؤى، وتعزيز التعبئة التنظيمية والنضالية، بما يخدم الدفاع عن الحقوق والمكتسبات للممرضين وتقنيي الصحة، والنهوض بالقضية التمريضية، وترسيخ هوية مهنية واضحة ومنصفة.\n\nواستهل المجلس أشغاله بتهنئة الشعب المغربي بعيدي الوحدة والمسيرة الخضراء، والتنويه بما تحققه بلادنا من تقدم في قضية الصحراء المغربية. ثم ناقش تعديلات النظام الداخلي، وتحيين الملف المطلبي، وتقييم المرحلة الحالية، حيث عبّر المتدخلون عن استيائهم من التراجعات التي تمس المكتسبات وتنصل الوزارة من الاتفاقات السابقة، خاصة اتفاق 23 يوليوز 2024.\n\nوبعد نقاش جاد ومستفيض، أجمع المجلس الوطني على:\n\n• تشبث النقابة بجميع بنود اتفاق 23 يوليوز 2024، وعلى رأسها الحفاظ على مركزية المناصب المالية والأجور، والتعجيل بتنزيل مقتضياته كاملة.\n• الانفتاح على الهيئات السياسية والإعلامية والجمعوية للتعريف بالقضية التمريضية.\n• الاستعداد التام لخوض معركة نضالية بلا هوادة من أجل الترافع على هوية تمريضية واضحة.\n• جعل جولات الحوار وسيلة لا غاية، نظراً لتنصل الوزارة من تنزيل اتفاقاتها.\n• تفويض تدبير المرحلة المقبلة للمكتب الوطني، مع الرجوع إلى الهياكل لحسم القرارات النهائية والكبرى.\n\nوختم أعضاء المجلس الوطني بالتعبير عن استعدادهم التام للتعاون والعمل على إنجاح هذه المرحلة والمضي قدماً بالقضية التمريضية.\n\nعاشت النقابة المستقلة للممرضين وتقنيي الصحة حرة، أبية ومناضلة. ✌🏻✌🏻",date:"2026-11-10",r:"وطني",src:"المجلس الوطني",url:"",img:["images/news/conseil-national-balagh-2026-11-07-poster.jpg","images/news/conseil-national-balagh-2026-11-07.jpg"],vid:"images/news/conseil-national-balagh-2026-11-07.mp4"},
    {t:"ميروش لـ«سفيركم»: إدراج أجور الصحة ضمن نفقات المعدات «النقطة التي أفاضت الكأس» والنقابة تتجه نحو التصعيد",c:"إعلام",d:"أثار إدراج أجور موظفي قطاع الصحة ضمن ميزانية «النفقات المختلفة والمعدات»، بدل فصل مستقل ضمن نفقات الموظفين في الميزانية العامة للدولة، موجة غضب داخل القطاع، وذلك في مشروع الميزانية الفرعية لوزارة الصحة والحماية الاجتماعية برسم سنة 2027.\n\nواعتبر عبد الله ميروش، الكاتب الوطني للنقابة المستقلة للممرضين وتقنيي الصحة، في تصريح لموقع «سفيركم»، أن هذا التوجه شكّل «النقطة التي أفاضت الكأس»، مؤكداً أن مكتسبات الموظفين أصبحت مهددة، وأن ذلك يتناقض مع التزامات اتفاق 23 يوليوز 2024.\n\nوحذّر ميروش من أن هذا الوضع قد يمهّد مستقبلاً لتفويت تدبير القطاع إلى الخواص، مؤكداً أن النقابة تتجه نحو التصعيد، وأن الاحتقان داخل القطاع مرشح للعودة بقوة أكبر.\n\nفي المقابل، أكد وزير الصحة والحماية الاجتماعية، خلال تقديم ميزانية الوزارة أمام لجنة القطاعات الاجتماعية بمجلس النواب، أن ميزانية 2027 تتضمن إحداث 8000 منصب مالي، منها 2600 منصب للمجموعات الصحية الترابية، فيما شددت الوزارة على أن محضر اتفاق 23 يوليوز 2024 يضمن الحفاظ على صفة الموظف العمومي واستمرار أداء الأجور من الميزانية العامة عبر الخزينة العامة.\n\nغير أن النقابات ترى أن ضمانات الاستقرار لا تكفيها التصريحات، بل يجب أن تنعكس فعلياً في طريقة إعداد الميزانية وتصنيف الأجور، وهو ما ينذر بتجدد التوتر بين الشغيلة الصحية والوزارة ما لم تُقدَّم توضيحات كافية.",date:"2026-11-10",r:"وطني",src:"سفيركم",url:"https://safircom.com/2026/11/10/bjijou-2-2/"},
    {t:"ميروش لـ«الشعاع»: قطاع الصحة يتجه نحو احتقان جديد قد يكون أشد من أزمة 2024 بسبب تعثر تنفيذ اتفاق يوليوز",c:"إعلام",d:"حذّر عبد الله ميروش، الكاتب الوطني للنقابة المستقلة للممرضين وتقنيي الصحة، في تصريح لجريدة «الشعاع»، من أن قطاع الصحة يتجه نحو مرحلة احتقان جديدة قد تكون أشد حدة من أزمة 2024، بسبب تراجع الوزارة والحكومة عن التزامات أساسية تضمنها اتفاق يوليوز 2024.\n\nوأوضح ميروش أن الاتفاق نص على الحفاظ على المكتسبات السابقة للشغيلة الصحية وإقرار تحفيزات جديدة تكرس الخصوصية المهنية للقطاع، غير أن تنزيله اتجه نحو تفعيل البنود والمراسيم التي تخدم الإدارة، مع إغفال مقتضيات التحفيز وتحسين الأوضاع المهنية والاجتماعية، واستمرار المماطلة في تنفيذها.\n\nوانتقد الكاتب الوطني دفع عشرات الآلاف من موظفي الصحة نحو المجموعات الصحية الترابية، معتبراً أن التجربة تعرف اختلالات متعددة يطبعها منطق التسلط والتدبير الأحادي، وتجاوز المقاربة التشاركية وتهميش الأدوار النقابية، فضلاً عن ممارسات تهديد وتنكيل وشطط في حق الموظفين.\n\nوأشار إلى أن الانتقال إلى وضعية مستخدمين رافقه تغيير في تصنيف أجور الموظفين، التي انتقلت من خانة نفقات الموظفين إلى خانة المعدات.\n\nوحذر ميروش من أن استمرار هذا الوضع سيعمق الاحتقان داخل القطاع ويرفع منسوب التوتر خلال الأيام المقبلة، ما لم تستجب الحكومة والوزارة الوصية لمطالب الشغيلة الصحية وتنفذ التزامات اتفاق يوليوز 2024.",date:"2026-11-10",r:"وطني",src:"الشعاع",url:"https://choae.com/yrfd",img:"images/news/mirouch-choae-2026-11-10.jpg"},
    {t:"فيديو | فاس: مسيرة احتجاجية خارج أسوار المركز الاستشفائي الجامعي الحسن الثاني دفاعاً عن تعويضات الحراسة",c:"وقفة احتجاجية",d:"خاض المكتب الجامعي للنقابة المستقلة للممرضين وتقنيي الصحة بالمركز الاستشفائي الجامعي الحسن الثاني بفاس، اليوم الثلاثاء 10 نونبر 2026، وقفة احتجاجية تلتها مسيرة خارج أسوار المركز، تحت شعار «صمتنا انتهى.. ونضالنا مستمر»، وذلك تنفيذاً للبرنامج النضالي المعلن في بيان 17 أكتوبر 2026.\n\nورفع المشاركون لافتات تطالب بصرف تعويضات الحراسة والمداومة عن سنوات 2024 و2025 و2026، مؤكدين أن «تعويضات الحراسة حق قانوني وتنظيمي، وليست امتيازاً قابلاً للتعطيل».\n\nشاهدوا الفيديو أعلاه.",date:"2026-11-10",r:"فاس",src:"المكتب الجامعي للمستشفيات الجامعية - فاس",url:"",vid:"images/news/fes-chu-masira-2026-11-10.mp4",img:"images/news/fes-chu-masira-2026-11-10.jpg"},
    {t:"الحسيمة: عماد البلوقي ينتقد تخصيص 206 مناصب فقط للأطر الصحية بجهة طنجة تطوان الحسيمة ويثير أزمة الانتقالات",c:"إعلام",d:"أثار الإعلان عن تخصيص 206 مناصب مالية فقط لتوظيف الأطر الصحية بالمجموعة الصحية الترابية لجهة طنجة تطوان الحسيمة، برسم ميزانية 2026، انتقادات بشأن مدى استجابة هذه الحصيصة لحجم الخصاص الذي تعاني منه المؤسسات الصحية بمختلف أقاليم الجهة.\n\nوفي هذا السياق، انتقد عماد البلوقي، ممرض بالمستشفى الإقليمي محمد السادس بالحسيمة وعضو النقابة المستقلة للممرضين وتقنيي الصحة، عدد المناصب المرتقبة، معتبراً أنها لا تعكس الاحتياجات الفعلية للمؤسسات الصحية، ولا تواكب التحديات المطروحة أمام إصلاح المنظومة الصحية وتنزيل الجهوية المتقدمة.\n\nوحذر البلوقي، في تدوينة له، من أن محدودية التوظيف ستزيد الضغط على الأطر التمريضية والتقنية التي تواصل العمل في ظل الخصاص المسجل، وهو ما قد ينعكس على ظروف اشتغالها وجودة الخدمات الصحية المقدمة للمواطنين.\n\nكما أثار إشكالية الانتقالات، مشيراً إلى أن قلة المناصب قد تعرقل التحاق عدد من الموظفين بمقرات عملهم الجديدة، رغم حصولهم على مقررات انتقال قانونية، بسبب صعوبة تعويض الخصاص الذي ستخلفه مغادرتهم لمقرات عملهم الحالية.\n\nولفت البلوقي إلى محدودية فرص التوظيف في عدد من التخصصات، من بينها الصحة النفسية، والترويض الطبي، وتصحيح النطق، والنفس الحركي، وتقويم البصر، وصيانة المعدات البيوطبية، وعلاجات المواليد والأطفال، وصحة الأسرة والصحة الجماعاتية، فضلاً عن المساعدة الاجتماعية، معتبراً أن عدم توفير مناصب كافية لهذه التخصصات قد يؤثر على تكامل الخدمات الصحية، ويحد من قدرة المؤسسات الاستشفائية على تقديم رعاية شاملة.\n\nوفي ما يتعلق ببطالة الخريجين، أكد أن المناصب المرتقبة لن تكون كافية لاستيعاب الأعداد المتزايدة من خريجي المعاهد العليا للمهن التمريضية وتقنيات الصحة، في ظل التفاوت بين عدد الباحثين عن العمل والفرص المتاحة.\n\nودعا وزارة الصحة والحماية الاجتماعية وإدارة المجموعة الصحية الترابية بالجهة إلى مراجعة سياسة تدبير الموارد البشرية، بما يضمن توزيعاً عادلاً للمناصب وفق الخصاص الفعلي، وإدماج مختلف التخصصات، إلى جانب إيجاد حلول عملية لملف الانتقالات.",date:"2026-11-10",r:"الحسيمة",src:"تيلي ناظور",url:"",img:"images/news/hoceima-belouki-2026-11-10.jpg"},
    {t:"الرباط: لا للتطاول على كرامة الشغيلة الصحية، بيان استنكاري للمكتب المحلي بالمعهد الوطني للأنكولوجيا",c:"بيان احتجاجي",d:"على إثر ما تم تداوله عبر مواقع التواصل الاجتماعي من شريط فيديو يوثق واقعة تعرض الأطر الصحية العاملة بوحدة المستعجلات بالمعهد الوطني للأنكولوجيا بالرباط للقذف والإهانة من طرف أحد المرتفقين، يعبر المكتب المحلي للنقابة المستقلة للممرضين وتقنيي الصحة عن إدانته الشديدة واستنكاره المطلق لهذه التصرفات غير المقبولة، التي تمس بكرامة مهنيي الصحة، وتسيء إلى حرمة المؤسسات الصحية، وتهدد السير العادي للخدمات المقدمة للمرضى.\n\nوإذ يعلن المكتب المحلي تضامنه المطلق واللامشروط مع الأطر الصحية المعنية، فإنه يؤكد أن هذه الواقعة لا يمكن فصلها عن واقع الاختلالات التنظيمية والبنيوية التي تعاني منها وحدة المستعجلات، وفي مقدمتها غياب الخدمات المساندة المكلفة بنقل المرضى ومرافقتهم بين مختلف المصالح والوحدات الاستشفائية، ومساعدتهم ومساعدة مرافقيهم، فضلاً عن الخصاص في عناصر الأمن الخاص المؤهلة للتدخل وحماية الأطر الصحية والمرضى والمرتفقين.\n\nكما يسجل المكتب المحلي، بقلق بالغ، الوضع غير المقبول الذي يتم فيه تدبير وحدة المستعجلات خلال يومي السبت والأحد بممرضة واحدة وطبيب واحد فقط، في ظل العدد الكبير من المرضى والمرتفقين، وما يترتب عن ذلك من ضغط مهني ونفسي متزايد، وظروف عمل لا تضمن الحد الأدنى من السلامة المهنية وجودة التكفل بالمرضى.\n\nإن استمرار هذه الاختلالات يخلق بيئة مشحونة بالتوتر والاحتقان، ويجعل الأطر الصحية في مواجهة مباشرة مع غضب المرتفقين واستيائهم من ظروف الاستقبال والتكفل، رغم أن معالجة هذه الإكراهات التنظيمية وتوفير الموارد البشرية واللوجستيكية اللازمة يندرجان ضمن مسؤوليات الإدارة، ولا يمكن بأي حال تحميل تبعاتهما للعاملين في الصفوف الأمامية. كما أن ما أظهرته الواقعة من توتر وتصعيد في التعامل يطرح بجدية احتمال تطور مثل هذه الأحداث إلى اعتداءات جسدية قد تكون عواقبها وخيمة، وهو ما يستدعي اتخاذ تدابير وقائية عاجلة قبل وقوع ما لا تحمد عقباه.\n\nوأمام هذه الوضعية، فإن المكتب المحلي:\n▪️ يدين بشدة كل أشكال السب والقذف والإهانة والاعتداء التي تستهدف الأطر الصحية أثناء أداء واجبها المهني، ويؤكد رفضه المطلق لأي مساس بكرامتها وسلامتها.\n▪️ يحمّل إدارة المعهد مسؤوليتها الكاملة في توفير شروط العمل الآمنة والملائمة، واتخاذ التدابير التنظيمية والوقائية الضرورية لحماية الشغيلة الصحية والمرضى والمرتفقين.\n▪️ يطالب بالتعزيز الفوري للموارد البشرية بوحدة المستعجلات، خصوصاً خلال أيام السبت والأحد والعطل، بما يتناسب مع حجم النشاط وضغط العمل.\n▪️ يدعو إلى توفير خدمات نقل المرضى ومساعدتهم بشكل منتظم وفعال، مع تعزيز عناصر الأمن الخاص وتحديد آليات واضحة للتدخل السريع عند وقوع حوادث التهديد أو الاعتداء.\n▪️ يطالب إدارة المعهد بتحمل مسؤوليتها في مؤازرة الأطر الصحية المتضررة، واتخاذ الإجراءات الإدارية والقانونية المناسبة لحماية كرامتها وصون حقوقها.\n▪️ يؤكد أن تحسين ظروف استقبال المرضى والتكفل بهم وحماية حقوقهم يمران بالضرورة عبر توفير ظروف عمل تحفظ كرامة الأطر الصحية وتضمن سلامتها.\n\nوفي الختام، يجدد المكتب المحلي تأكيده أن كرامة الشغيلة الصحية وسلامتها خط أحمر، وأن استمرار الخصاص والاختلالات التنظيمية لا يمكن أن يشكل مبرراً لتعريضها للمخاطر أو تركها في مواجهة مباشرة مع توترات المرتفقين دون حماية أو دعم مؤسساتي، كما يدعو إدارة المعهد إلى التدخل العاجل والمسؤول لمعالجة هذه الاختلالات، ويحمّلها مسؤولية ما قد يترتب عن استمرارها من تداعيات.\n\nعاشت النقابة المستقلة للممرضين وتقنيي الصحة، حرة، مستقلة ومناضلة.",date:"2026-11-09",r:"الرباط",src:"المكتب المحلي بالمعهد الوطني للأنكولوجيا بالرباط",url:"",img:"images/news/rabat-ino-2026-11-09.jpg"},
    {t:"أكادير: توقيع محضر اجتماع بين إدارة المجموعة الصحية الترابية سوس ماسة والتنسيق النقابي الجامعي بعد أزيد من ست ساعات من الحوار",c:"تنظيم",d:"إخبار لعموم الشغيلة الصحية بالمستشفيات الجامعية وعموم الرأي العام المهتم بالشأن الصحي المحلي والجهوي والوطني:\n\nبدعوة من إدارة المجموعة الصحية الترابية سوس ماسة، انعقد يوم الإثنين 9 نونبر 2026 لقاء مع مسؤولي الإدارة العامة بحضور مدراء المستشفيات الجامعية، ودام الاجتماع لأزيد من ست ساعات من النقاش المسؤول والمستفيض، خُصص للتداول في مختلف الملفات المطلبية والقضايا المهنية والإدارية المطروحة على مستوى المؤسسات الاستشفائية الجامعية داخل المجموعة.\n\nوقد استحضر التنسيق النقابي الجامعي، الذي يجمع النقابة المستقلة للممرضين وتقنيي الصحة والنقابة المستقلة للأطر الإدارية والتقنية ومساعدي الصحة، جملة من الاختلالات والإشكالات، ووضع على طاولة الحوار ملفاً مطلبياً يشمل هموم جموع الأطر الصحية بجميع المستشفيات الجامعية، مؤكداً أن تدبير المرحلة يقتضي الإنصات الجاد والمسؤول والوضوح في المواقف وتحمل المسؤولية في اتخاذ القرارات لنزع فتيل الاحتقان وترسيخ السلم الاجتماعي.\n\nوتُوّج اللقاء بتوقيع محضر اجتماع بين المسؤولين والتنسيق النقابي الجامعي تضمّن عدداً من الالتزامات المرتبطة بالملفات موضوع النقاش، في انتظار بلاغ تفصيلي سيصدر يوم غد يتضمن مختلف الملفات التي نوقشت والالتزامات المتفق عليها، كما سيحدد مصير البرنامج النضالي الذي سبق إقراره، بما في ذلك المقاطعة والاعتصام الجزئي، وتاريخ الجلسة الثانية من الحوار التي تعهدت بها الإدارة.\n\nونثمّن مبادرة اليد الممدودة والانفتاح على التنسيق النقابي الجامعي، في أفق عقد جلسة حوار ثانية وتنزيل نقاط المحضر الذي توج به الاجتماع، شريطة أن يُحدث هذا الحوار التغيير ويستجيب لأماني وانتظارات الشغيلة الصحية.",date:"2026-11-09",r:"أكادير",src:"المكتبان الجامعيان بالمؤسسات الاستشفائية الجامعية بالمجموعة الصحية الترابية سوس ماسة",url:"",img:["images/news/agadir-chu-liqa-2026-11-09.jpg","images/news/agadir-chu-balagh-2026-11-09.jpg"]},
    {t:"كلميم: بيان استنكاري وتضامني مع الممرض (أ.ح) إثر الاعتداء الجسدي الخطير الذي تعرض له بالمركز الصحي الحضري بويزكارن",c:"بيان احتجاجي",d:"على إثر الاعتداء الجسدي الخطير الذي تعرض له الممرض (أ.ح) بالمركز الصحي الحضري بويزكارن صباح يوم الإثنين 09 نونبر 2026، أثناء مزاولته لعمله بكل مهنية وتفانٍ، من قبل أحد المرتفقين في واقعة خطيرة وسلوك إجرامي مرفوض يمس بكرامة مهنيي الصحة وسلامتهم الجسدية والنفسية، حيث نُقل الممرض المعتدى عليه إلى المستشفى المحلي بويزكارن ثم إلى المركز الاستشفائي الجهوي كلميم وهو في حالة خطيرة ومزرية، تدخّل أعضاء المكتب الإقليمي واتُّخذت جميع الإجراءات القانونية، مع التواصل مع المندوبية الإقليمية والمدير الجهوي للصحة والحماية الاجتماعية والوقوف بجانب الممرض ودعمه ومساندته.\n\nويعبّر المكتب الإقليمي للنقابة المستقلة للممرضين وتقنيي الصحة بكلميم عن إدانته الشديدة واستنكاره المطلق لهذا السلوك الإجرامي، الذي يشكل مساساً خطيراً بالكرامة الإنسانية والمهنية للأطر الصحية، واعتداءً سافراً على حرمة المؤسسات الصحية، مؤكداً أن المؤسسات الصحية ليست فضاءات مستباحة للاعتداء والترهيب والإهانة، وأن الممرض ليس حائطاً قصيراً لتفريغ الغضب والاحتقان الناتجين عن اختلالات المنظومة الصحية.\n\nوعليه، فإن المكتب الإقليمي:\n▪️ يدين بأشد العبارات هذا الاعتداء اللفظي والجسدي، ويعتبره سلوكاً مرفوضاً لا يمكن التساهل معه.\n▪️ يعلن تضامنه الكامل مع الممرض (أ.ح)، وسيسلك جميع المساطر القانونية والقضائية من أجل إنصافه وحماية كرامته.\n▪️ يطالب المندوبية الإقليمية والجهوية للصحة والحماية الاجتماعية بكلميم وادنون بتحمل مسؤولياتها كاملة في توفير الحماية اللازمة للأطر الصحية أثناء مزاولتها لمهامها، واتخاذ إجراءات عاجلة وفعالة للحد من تكرار مثل هذه الاعتداءات.\n▪️ يدعو الجهات المختصة إلى التطبيق الصارم للقوانين الزجرية في حق كل من يعتدي على مهنيي الصحة أثناء أداء واجبهم المهني، ضماناً لهيبة المرفق العمومي وصوناً لكرامة العاملين به.\n▪️ يطالب الإدارة الجهوية بتنزيل مضامين دورية وزارة العدل عدد 42 س/ر.ن/ع/2021.\n▪️ يجدد مطالبته بتعزيز إجراءات الأمن والحماية داخل المؤسسات الصحية، وإيجاد حل لمشكل غياب حراس الأمن بمختلف المؤسسات الصحية، مؤكداً أنه لن يتراجع إلى حين حل هذا الإشكال.\n\nوختاماً، يؤكد المكتب الإقليمي أن كرامة وسلامة الممرضين وتقنيي الصحة خط أحمر، وأنه يحتفظ بحقه في اتخاذ كافة الأشكال النضالية.",date:"2026-11-09",r:"كلميم",src:"المكتب الإقليمي بكلميم",url:"",img:"images/news/bouizakarne-bayan-2026-11-09.jpg"},
    {t:"كلميم: انتخاب أيوب الدغيش كاتباً محلياً للمركز الاستشفائي الجهوي ومنير العسري كاتباً محلياً لوكالة الدم ومشتقاته",c:"تنظيم",d:"في إطار مواصلة البناء التنظيمي وتجديد هياكل النقابة المستقلة للممرضين وتقنيي الصحة بجهة كلميم وادنون، انعقد اليوم الإثنين 09 نونبر 2026 على الساعة 16:30 مساءً، بقاعة الاجتماعات بالمندوبية الإقليمية لوزارة الصحة والحماية الاجتماعية بكلميم، الجمع العام التجديدي للمكتب المحلي للمركز الاستشفائي الجهوي كلميم، والجمع العام التأسيسي للمكتب المحلي لوكالة الدم ومشتقاته كلميم وادنون، وذلك بحضور الكاتب الجهوي وأعضاء المكتب الوطني، وفي أجواء طبعتها روح المسؤولية والديمقراطية التنظيمية والالتزام النقابي والنقاش الجاد.\n\nوقد تم انتخاب:\n▪️ المناضل أيوب الدغيش كاتباً محلياً جديداً للمكتب المحلي للمركز الاستشفائي الجهوي كلميم.\n▪️ المناضل منير العسري كاتباً محلياً للمكتب المحلي لوكالة الدم ومشتقاته كلميم وادنون.\n\nوإذ نهنئ الأخوين على الثقة التي حظيا بها، فإننا نعتبر هذه المحطة التنظيمية تجسيداً لإرادة جماعية تروم تجديد النخب والهياكل، وتوسيع قاعدة التنظيم، وتعزيز آليات التأطير والترافع عن مطالب الممرضين وتقنيي الصحة.\n\nونؤكد تجدد الالتزام، واستمرارية العطاء، ووحدة الممرضين وتقنيي الصحة في إطارهم؛ فالمسؤولية تكليف، والثقة أمانة، والنضال ممارسة يومية لا تُختزل في المواقع والصفات.\n\nكل التوفيق للمكتبين المحليين في مهامهما التنظيمية والنضالية. وعاشت النقابة المستقلة للممرضين وتقنيي الصحة صامدة حرة أبية.",date:"2026-11-09",r:"كلميم",src:"المكتب الجهوي بجهة كلميم وادنون",url:"",img:["images/news/guelmim-jg-2026-11-09-1.jpg","images/news/guelmim-jg-2026-11-09-2.jpg"]},
    {t:"أكادير: اعتصام جزئي بمبيت ليلي أمام مكتب مدير المجموعة الصحية الترابية سوس ماسة يوم الثلاثاء 10 نونبر",c:"بيان احتجاجي",d:"في ظل استمرار سياسة التجاهل والتعنت التي تنهجها الإدارة في التعاطي مع الملفات المطلبية العادلة والمشروعة للشغيلة الصحية بالمؤسسات الاستشفائية الجامعية التابعة للمجموعة الصحية الترابية سوس ماسة، وأمام تنامي منطق القرارات الأحادية وغياب الحوار المؤسساتي الجاد والمسؤول، يعلن التنسيق النقابي الفئوي الذي يجمع المكتب الجامعي للنقابة المستقلة للممرضين وتقنيي الصحة والمكتب الجامعي للنقابة المستقلة للأطر الإدارية والتقنية ومساعدي الصحة عن خوض اعتصام جزئي.\n\n📅 يوم الثلاثاء 10 نونبر 2026\n🕟 من الساعة 16:30 زوالاً إلى الساعة 08:00 صباحاً، مرفوقاً بمبيت ليلي\n📍 أمام مكتب مدير المجموعة الصحية الترابية سوس ماسة بإدارة مستشفى التخصصات بأكادير\n\nوذكّر المكتبان الجامعيان المدير العام للمجموعة بأن المسؤولية الإدارية ليست سلطة للتسلط، وأن الحوار الاجتماعي ليس امتيازاً يُمنح ويُحجب متى شاءت الإدارة. «اخترنا الحوار، لكننا لن نقبل أن يتحول إلى غطاء للتسويف، واحترامنا للمؤسسات لا يعني خضوعنا للقرارات الأحادية».\n\nفالنضال لا يُدار بالتعليمات ولا ترهبه المناصب.",date:"2026-11-08",r:"أكادير",src:"المكتبان الجامعيان بالمؤسسات الاستشفائية الجامعية بالمجموعة الصحية الترابية سوس ماسة",url:"",img:"images/news/agadir-chu-iatisam-2026-11-10.jpg"},
    {t:"فاس: «صمتنا انتهى.. ونضالنا مستمر»، وقفة ومسيرة احتجاجية بالمستشفيات الجامعية يوم الثلاثاء 10 نونبر دفاعاً عن تعويضات الحراسة",c:"وقفة احتجاجية",d:"«صمتنا انتهى.. ونضالنا مستمر»\n\nيخوض المكتب الجامعي للنقابة المستقلة للممرضين وتقنيي الصحة بالمستشفيات الجامعية بفاس، بمعية المكتب الجهوي بجهة فاس-مكناس، وقفة احتجاجية تعقبها مسيرة يوم الثلاثاء 10 نونبر 2026، تنفيذاً للبرنامج النضالي الذي أعلنه في بيانه المستعجل الصادر يوم 17 أكتوبر 2026.\n\n📍 مكان التجمع: أمام الإدارة العامة\n🕦 11:30 بداية التجمع وتوزيع اللافتات\n🕛 12:00 انطلاق المسيرة نحو إدارة مستشفى التخصصات، ثم الخروج إلى خارج أسوار المستشفى مروراً بالقرب من كلية الطب والصيدلة، والدخول من الباب المقابل لمركز تحاقن الدم\n🕐 13:00 العودة إلى نقطة التجمع\n🎙️ 13:15 كلمة الكاتب الجهوي والكاتب الجامعي وأعضاء المكتبين الجامعي والجهوي\n\nوتأتي هذه الخطوة احتجاجاً على استمرار التأخر غير المقبول في صرف تعويضات الحراسة والمداومة المستحقة عن سنوات 2024 و2025 و2026، ورفض صرفها بالصيغة القانونية كما أقرها المرسوم رقم 2.25.1067 والقرار الوزاري رقم 650.26 المنشور بالجريدة الرسمية بتاريخ 9 أبريل 2026، وتعبيراً عن رفض سياسة التسويف والتماطل في تسوية الوضعية الإدارية والمالية للممرضين وتقنيي الصحة.\n\nويدعو المكتب الجامعي المشاركين إلى ارتداء الوزرة المهنية والالتزام بالانضباط والطابع السلمي والحضاري، مؤكداً أنه سيعقد اجتماعاً مباشرة بعد انتهاء الأشكال النضالية المسطرة لتقييم مآل الملف وتسطير برنامج نضالي أكثر تصعيداً، إلى حين صرف المستحقات كاملة.\n\nالكل مدعو للمشاركة، حضوركم قوتنا. فلا حقوق تُنتزع دون نضال، ولا كرامة تُصان دون وحدة وتضامن.",date:"2026-11-08",r:"فاس",src:"المكتب الجامعي للمستشفيات الجامعية - فاس",url:"",img:["images/news/fes-chu-wakfa-2026-11-10.jpg","images/news/fes-chu-wakfa-2026-11-10-fiche.jpg","images/news/fes-chu-bayan-2026-10-17.jpg"]},
    {t:"بويزكارن: تجديد المكتب المحلي لدائرة بويزكارن يوم الأربعاء 11 نونبر 2026",c:"تنظيم",d:"في إطار مواصلة الاستعداد للرهانات المقبلة والتحديات المستقبلية، وفي إطار مواصلة الهيكلة التنظيمية للنقابة المستقلة للممرضين وتقنيي الصحة بجهة كلميم وادنون، تتشرف النقابة بدعوتكم لحضور الجمع العام لتجديد المكتب المحلي لدائرة بويزكارن بإقليم كلميم.\n\n📅 يوم الأربعاء 11 نونبر 2026\n🕓 على الساعة الرابعة مساءً (16:00)\n📍 قاعة الاجتماعات بالمستشفى المحلي بويزكارن\n\nنواصل المسار.",date:"2026-11-08",r:"كلميم",src:"المكتب الجهوي بجهة كلميم وادنون",url:"",img:"images/news/bouizakarne-2026-11-11.jpg"},
    {t:"في الذكرى التاسعة لاستشهاد الممرضة السعدية جيدور",c:"ذكرى",d:"في مثل هذا اليوم، 9 نونبر 2017، استشهدت الممرضة متعددة الاختصاصات السعدية جيدور بضواحي إقليم الصويرة، وهي تؤدي واجبها المهني في خدمة المرضى.\n\nتسع سنوات مرت، وما زالت ذكراها حاضرة بيننا، شاهدةً على تضحيات الممرضين وتقنيي الصحة وعلى ظروف العمل الصعبة التي يواجهونها كل يوم.\n\nوإذ نستحضر روحها الطاهرة، تجدد النقابة المستقلة للممرضين وتقنيي الصحة العهد على مواصلة النضال من أجل ظروف عمل آمنة وكريمة لكل نساء ورجال الصحة.\n\nذكراها أمانة، ونضالنا من أجل ظروف عمل آمنة عهدٌ لا نحيد عنه.\nرحمها الله وأسكنها فسيح جناته.",date:"2026-11-09",from:"2026-11-08",pin:"2026-11-20",r:"",src:"النقابة المستقلة للممرضين وتقنيي الصحة",url:"",vid:"images/news/saadia-jiddour-2026-11-09.mp4",img:["images/news/saadia-jiddour-2026-11-09.jpg","images/news/saadia-jiddour-2026-11-09-story.jpg"]},
    {t:"تهنئة بمناسبة اليوم العالمي للأشعة",c:"المكتب الوطني",d:"بمناسبة اليوم العالمي للأشعة، الذي يصادف 8 نونبر من كل سنة، ذكرى اكتشاف الأشعة السينية على يد العالم فيلهلم كونراد رونتغن سنة 1895، تتقدم النقابة المستقلة للممرضين وتقنيي الصحة بأحرّ التهاني وأصدق عبارات التقدير إلى كافة تقنيات وتقنيي الأشعة، بالمستشفيات والمراكز الصحية عبر ربوع المملكة.\n\nأنتم العين التي ترى ما لا يُرى. خلف كل تشخيص دقيق صورةٌ التقطتها أيديكم، وخلف كل صورة كفاءةٌ ومسؤولية والتزام يومي في خدمة المرضى، رغم ضغط العمل ونقص الموارد البشرية والتجهيزات.\n\nوبهذه المناسبة، تجدد النقابة مطالبتها بتوفير وسائل الوقاية والحماية من الإشعاع واحترام معايير السلامة الإشعاعية بجميع المصالح، والتتبع الطبي المنتظم والقياس الدوري لجرعات الإشعاع لكل العاملين، وتعويض عن الأخطار المهنية يتناسب مع حجم المخاطر، وسد الخصاص في الموارد البشرية وتوفير ظروف عمل آمنة وكريمة.\n\nكل عام وأنتم عين الطب ونبض التشخيص.",date:"2026-11-08",r:"",src:"النقابة المستقلة للممرضين وتقنيي الصحة",url:"",img:"images/news/radiologie-2026-11-08.jpg"},
    {t:"انعقاد الدورة العادية الأولى للمجلس الوطني بالدار البيضاء",c:"المكتب الوطني",d:"انعقدت يوم السبت 7 نونبر 2026 الدورة العادية الأولى للمجلس الوطني للنقابة المستقلة للممرضين وتقنيي الصحة بعد المؤتمر الوطني الثاني (والسابعة منذ التأسيس)، بالخزانة البلدية بالحي المحمدي بالدار البيضاء، تحت شعار «الهوية التمريضية: فكر وبناء ونضال»، بحضور أعضاء المجلس الوطني من مختلف جهات المملكة، وذلك قبل اللقاء الأول مع السيد وزير الصحة والحماية الاجتماعية.\n\nومرّت أشغال المجلس في جو ساده نقاش جاد ومثمر من جميع أعضائه، تناول مستجدات الساحة، وأولويات الملف المطلبي، وطريقة تدبير المرحلة المقبلة، والتحديات والرهانات المستقبلية.\n\nوعرفت أشغال المجلس لحظة تكريم لوجوه أعطت الكثير للقضية التمريضية، عرفاناً بعطائها ونضالها في سبيل كرامة وحقوق الممرضين وتقنيي الصحة.\n\nنواصل المسار.",date:"2026-11-07",r:"الدار البيضاء",src:"المكتب الوطني",url:"",img:["images/news/conseil-national-2026-11-07-collage.jpg","images/news/conseil-national-2026-11-07-photo1.jpg","images/news/conseil-national-2026-11-07-photo2.jpg","images/news/conseil-national-2026-11-07-salle.jpg","images/news/conseil-national-2026-11-07-salle2.jpg","images/news/conseil-national-2026-11-07-takrim1.jpg","images/news/conseil-national-2026-11-07-takrim2.jpg","images/news/conseil-national-2026-11-07-takrim3.jpg","images/news/conseil-national-2026-11-07-takrim4.jpg"]},
    {t:"ميدلت: المؤتمر الإقليمي الثاني ينتخب أمين أوجيل كاتباً إقليمياً",c:"تنظيم",d:"عقدت النقابة المستقلة للممرضين وتقنيي الصحة مؤتمرها الإقليمي الثاني بإقليم ميدلت يوم السبت 31 أكتوبر 2026 بدار الشباب ابن خلدون بميدلت، تحت شعار «وحدتنا قوتنا... والنضال سبيلنا لانتزاع المطالب»، بمشاركة حاشدة لنساء ورجال التمريض من مختلف الدوائر والمؤسسات الصحية بالإقليم.\n\nوافتُتحت الأشغال بكلمة توجيهية للكاتب الجهوي السيد عبد الحق العزيزي، أكد فيها على ضرورة التشبث بالخيار النضالي المستقل كضامن لحماية الحقوق وصون الكرامة. وبعد عرض التقريرين الأدبي والمالي للمكتب المنتهية ولايته، صادق المؤتمرون عليهما بالإجماع، وكُرّم أعضاء المكتب الإقليمي السابق تقديراً لتفانيهم.\n\nوانتخب الجمع العام مكتباً إقليمياً جديداً بتزكية السيد أمين أوجيل كاتباً إقليمياً، إلى جانب تشكيلة تمثل مختلف المؤسسات والمراكز الصحية بالإقليم. وأعلن الحاضرون جاهزيتهم لمواصلة التعبئة والالتفاف حول إطارهم النقابي المستقل، سبيلاً لانتزاع الحقوق المشروعة وتحقيق العدالة المهنية لجميع الأطر التمريضية والتقنية بإقليم ميدلت.\n\nوبهذه المناسبة، يتقدم المكتب الجهوي للنقابة بجهة درعة تافيلالت بأحر التهاني وأصدق عبارات التبريك للأخ أمين أوجيل بمناسبة انتخابه كاتباً إقليمياً بإقليم ميدلت، متمنياً له كامل التوفيق والسداد في مهامه الجديدة، وللمكتب الإقليمي بكافة أعضائه مسيرة تنظيمية موفقة مليئة بالعطاء والعمل الجاد دفاعاً عن كرامة وحقوق الممرضين وتقنيي الصحة. ألف مبروك هذه الثقة المستحقة، وبالتوفيق للجميع.",date:"2026-11-07",r:"ميدلت",src:"رئاسة المؤتمر الإقليمي الثاني بميدلت والمكتب الجهوي بجهة درعة تافيلالت",url:"",img:["images/news/midelt-tahnia-2026-11-07.jpg","images/news/midelt-congres-2026-10-31.jpg","images/news/midelt-congres-2026-10-31-2.jpg"]},
    {t:"اجتماع المكتب الوطني بالدار البيضاء مباشرة بعد تأسيس المكتب الإقليمي بأنفا",c:"المكتب الوطني",d:"عقد المكتب الوطني للنقابة المستقلة للممرضين وتقنيي الصحة اجتماعاً يوم الجمعة 6 نونبر 2026 بالدار البيضاء، مباشرة بعد الجمع العام التأسيسي للمكتب الإقليمي بالمنطقة الصحية أنفا، وذلك عشية انعقاد الدورة العادية الأولى للمجلس الوطني يوم السبت 7 نونبر 2026.",date:"2026-11-06",r:"الدار البيضاء",src:"المكتب الوطني",url:"",img:["images/news/bureau-national-2026-11-06.jpg","images/news/bureau-national-2026-11-06-2.jpg","images/news/bureau-national-2026-11-06-3.jpg","images/news/bureau-national-2026-11-06-4.jpg"]},
    {t:"انتخاب الأخ بدر الدين أسراك كاتباً للمكتب الإقليمي بالمنطقة الصحية أنفا",c:"تنظيم",d:"انعقد الجمع العام التأسيسي للمكتب الإقليمي للنقابة المستقلة للممرضين وتقنيي الصحة بالمنطقة الصحية أنفا يوم الجمعة 6 نونبر 2026، وأسفر عن انتخاب الأخ بدر الدين أسراك كاتباً إقليمياً.\n\nهنيئاً للأخ بدر الدين أسراك ولأعضاء المكتب الإقليمي بالثقة التي حظوا بها، مع متمنياتنا لهم بالتوفيق في خدمة الممرضين وتقنيي الصحة والدفاع عن حقوقهم.",date:"2026-11-06",r:"أنفا",img:"images/news/anfa-asrak-2026-11-06.jpg"},
    {t:"كلميم: تجديد المكتب المحلي للمركز الاستشفائي الجهوي وتأسيس المكتب المحلي لوكالة الدم ومشتقاته يوم الإثنين 9 نونبر 2026",c:"تنظيم",d:"في إطار مواصلة الاستعداد للرهانات المقبلة والتحديات المستقبلية، ومواصلة الهيكلة التنظيمية للنقابة المستقلة للممرضين وتقنيي الصحة بجهة كلميم وادنون، يعقد المكتب الإقليمي بكلميم يوم الإثنين 9 نونبر 2026 على الساعة الرابعة مساءً (16:00)، بقاعة الاجتماعات بالمندوبية الإقليمية لوزارة الصحة والحماية الاجتماعية بكلميم:\n\n• الجمع العام التجديدي للمكتب المحلي للمركز الاستشفائي الجهوي كلميم.\n• الجمع العام التأسيسي للمكتب المحلي لوكالة الدم ومشتقاته كلميم وادنون.",date:"2026-11-05",r:"كلميم",src:"المكتب الإقليمي بكلميم",url:"",img:"images/news/guelmim-2026-11-09.jpg"},
    {t:"بيان إنذاري مشترك: التنسيق النقابي يدق ناقوس الخطر بالمركز الاستشفائي سيدي احساين بناصر بورزازات",c:"بيان احتجاجي",d:"أصدر التنسيق النقابي بورزازات، المكون من المكتب الإقليمي للنقابة المستقلة للممرضين وتقنيي الصحة والمكتب الإقليمي للنقابة المستقلة للأطر الإدارية والتقنية ومساعدي الصحة، يوم 4 نونبر 2026 بياناً إنذارياً مشتركاً يدق فيه ناقوس الخطر بشأن الأوضاع داخل المستشفى الإقليمي سيدي احساين بناصر ومستشفى التخصصات بوكافر بورزازات.\n\nويسجل البيان تفاقم الاختلالات الإدارية والتدبيرية، واستمرار غياب حوار اجتماعي جاد ومسؤول، والمساس باستقلالية القرار الإداري، وارتباك اتخاذ القرارات، وتداخل الاختصاصات في تدبير تداريب طلبة المعهد العالي للمهن التمريضية وتقنيات الصحة، والتأخر في صرف تعويضات الحراسة والإلزامية والمداومة عن 2025 و2026.\n\nكما يندد بالتماطل في تعيين رئيس قطب العلاجات التمريضية، وسوء تدبير الموارد البشرية، والتوزيع غير العادل للسكن الوظيفي، وتعطيل تفعيل مصلحة المساعدة الطبية المستعجلة (SAMU)، والوضعية المتردية لمقر المختبر، وتردي خدمات المطبخ والتغذية، والاختلالات في تدبير الأدوية والأجهزة الطبية، وإطالة فترات انتظار المرضى.\n\nوأمام هذه الأوضاع، يعلن التنسيق النقابي عن تنظيم وقفة احتجاجية إنذارية أمام المستشفى الإقليمي سيدي احساين بناصر يوم الخميس 12 نونبر 2026 على الساعة 11 صباحاً، ويهيب بكافة الممرضات والممرضين وتقنيي الصحة والأطر الإدارية والتقنية ومساعدي الصحة إلى التكتل ورص الصفوف والانخراط المكثف في هذه المحطة النضالية.\n\n«لقد استُنفدت لغة المراسلات والاجتماعات... فالكرامة المهنية ليست امتيازاً، والحقوق ليست مطالب قابلة للتأجيل، وتحمل المسؤولية لم يعد خياراً بل واجباً».",date:"2026-11-04",r:"ورزازات",src:"التنسيق النقابي بورزازات (النقابة المستقلة للممرضين وتقنيي الصحة والنقابة المستقلة للأطر الإدارية والتقنية ومساعدي الصحة)",url:"",img:["images/news/ouarzazate-bayan-2026-11-04.jpg","images/news/ouarzazate-bayan-2026-11-04-2.jpg","images/news/ouarzazate-bayan-2026-11-04-3.jpg","images/news/ouarzazate-bayan-2026-11-04-4.jpg","images/news/ouarzazate-bayan-2026-11-04-5.jpg","images/news/ouarzazate-bayan-2026-11-04-6.jpg"]},
    {t:"وقفة احتجاجية ناجحة أمام إدارة المستشفى الجهوي ابن زهر بمراكش",c:"وقفة احتجاجية",d:"نظم المكتب الإقليمي للنقابة المستقلة للممرضين وتقنيي الصحة بمراكش، بتنسيق مع النقابة المستقلة للأطر الإدارية والتقنية ومساعدي الصحة، يوم الأربعاء 4 نونبر 2026 وقفة احتجاجية ناجحة أمام إدارة المستشفى الجهوي ابن زهر بمراكش، دفاعاً عن الحقوق والمطالب المشروعة للشغيلة الصحية، تحت شعار «تعويضاتنا حق لا مكرمة».",date:"2026-11-04",r:"مراكش",src:"المكتب الإقليمي بعمالة مراكش",url:"",img:["images/news/marrakech-wakfa-2026-11-04.jpg","images/news/marrakech-wakfa-2026-11-04-2.jpg","images/news/marrakech-wakfa-2026-11-04-3.jpg"]},
    {t:"رئيسة الحكومة ترخص للمجموعة الصحية الترابية الدار البيضاء-سطات بمواصلة العمل باللجان الثنائية الحالية إلى غاية انتخابات 2027",c:"مستجدات مهنية",d:"منحت السيدة رئيسة الحكومة الترخيص الاستثنائي للمجموعة الصحية الترابية الدار البيضاء-سطات لمواصلة العمل باللجان الإدارية الثنائية المتساوية الأعضاء الحالية، إلى غاية انعقاد الانتخابات المقبلة لهذه اللجان سنة 2027.",date:"2026-11-04",r:"الدار البيضاء سطات",src:"النقابة المستقلة للممرضين وتقنيي الصحة",url:"",img:"images/news/gst-casa-2026-11-04.jpg"},
    {t:"الجمع العام التأسيسي للمكتب الإقليمي بأنفا يوم الجمعة 6 نونبر 2026",c:"تنظيم",d:"تعقد النقابة المستقلة للممرضين وتقنيي الصحة الجمع العام التأسيسي لمكتبها الإقليمي بأنفا، يوم الجمعة 6 نونبر 2026 على الساعة الثانية بعد الزوال (14:00)، بقاعة المرصد الجهوي للصحة، تحت شعار: «نبتكر الخطوة ونشكل الأثر».",date:"2026-11-04",r:"أنفا",src:"النقابة المستقلة للممرضين وتقنيي الصحة",url:"",img:"images/news/anfa-2026-11-06.jpg"},
    {t:"المجلس الوطني ينعقد يوم السبت 7 نونبر 2026 بالدار البيضاء",c:"المكتب الوطني",d:"تعقد النقابة المستقلة للممرضين وتقنيي الصحة الدورة العادية الأولى لمجلسها الوطني بعد المؤتمر الوطني الثاني، يوم السبت 7 نونبر 2026 ابتداءً من الساعة التاسعة صباحاً، بقاعة العروض بالخزانة البلدية بالحي المحمدي بالدار البيضاء، تحت شعار: «الهوية التمريضية: فكر وبناء ونضال»، وذلك قبل اللقاء الأول مع السيد وزير الصحة والحماية الاجتماعية. المجلس الوطني: رؤية وتصور للمرحلة المقبلة.",date:"2026-11-02",r:"وطني",src:"المكتب الوطني",url:"",img:["images/news/conseil-national-2026-11-07-shiar.jpg","images/news/conseil-national-2026-11-07.jpg"]},
    {t:"وقفة احتجاجية أمام المستشفى الجهوي ابن زهر بمراكش يوم الأربعاء 4 نونبر 2026",c:"وقفة احتجاجية",d:"يدعو المكتب الإقليمي للنقابة المستقلة للممرضين وتقنيي الصحة بعمالة مراكش جميع الممرضات والممرضين وتقنيي الصحة، المنخرطين والمهنيين بالقطاع الصحي، إلى تجسيد وقفة احتجاجية يوم الأربعاء 4 نونبر 2026 على الساعة الحادية عشرة صباحاً (11:00)، أمام إدارة المستشفى الجهوي ابن زهر بمراكش، تحت شعار: «تعويضاتنا حق لا مكرمة».",date:"2026-11-02",r:"مراكش",src:"المكتب الإقليمي بعمالة مراكش",url:""},
    {t:"تجديد المكتب الإقليمي بالنواصر وانتخاب سعد غزال كاتباً إقليمياً",d:"وفاءً لروح الكاتب الإقليمي السابق رحمه الله، انعقد يوم السبت 31 أكتوبر 2026 بالمركز الثقافي ببوسكورة الجمع العام التجديدي للمكتب الإقليمي بإقليم النواصر، بحضور الكاتب الوطني والكاتب الجهوي لجهة الدار البيضاء سطات وأعضاء المكتب الجهوي وضيوف الشرف. وتُوّجت أشغاله بانتخاب الممرض سعد غزال كاتباً إقليمياً، واعتماد التشكيلة الجديدة للمكتب الإقليمي: سعيدة أوبلا، مروان بركي، اسماعيل الضعيف وعبد الحق جابر نواباً للكاتب، ابتسام البوحي أمينة للمال وأمال مرزاق نائبة لها، وعبد الرحمان بن جلون مقرراً وسميرة لمتوح نائبة له.",c:"تنظيم",date:"2026-11-02",r:"النواصر",src:"المكتب الإقليمي بالنواصر",url:""},
    {t:"الوزير يدعو النقابات الصحية إلى اجتماع 14 نونبر حول تثمين الموارد البشرية",d:"دعا وزير الصحة والحماية الاجتماعية النقابات الصحية إلى اجتماع يوم 14 نونبر 2026 في إطار الحوار الاجتماعي القطاعي. وصرّح الكاتب الوطني عبد الله ميروش لهسبريس بأن النقابة ستطرح ملفها المطلبي بأبعاده الهوياتية والمادية والأكاديمية، بما فيها مطالب اتفاق يوليوز العالقة، ومطالب جديدة ينتظر أن يصادق عليها المجلس الوطني للنقابة يوم السبت 7 نونبر بالدار البيضاء.",c:"إعلام",date:"2026-11-01",r:"وطني",src:"هسبريس",url:"https://www.hespress.com/%d8%a8%d8%ac%d9%8a%d8%ac%d9%88-%d9%8a%d9%86%d8%a7%d9%82%d8%b4-%d8%aa%d8%ab%d9%85%d9%8a%d9%86-%d8%a7%d9%84%d9%85%d9%88%d8%a7%d8%b1%d8%af-%d8%a7%d9%84%d8%a8%d8%b4%d8%b1%d9%8a%d8%a9-1832328.html"},
    {t:"انتخاب منصف لمريبط كاتباً إقليمياً بسيدي سليمان",d:"بتأطير من المكتب الوطني والمكتب الجهوي لجهة الرباط سلا القنيطرة، انتُخب بالإجماع السيد منصف لمريبط كاتباً إقليمياً للنقابة بإقليم سيدي سليمان، في مؤتمر دام أزيد من أربع ساعات تدارس مشاكل القطاع بالإقليم. الصور في قسم «الأنشطة».",c:"أنشطة",date:"2026-10-31",r:"سيدي سليمان",src:"المكتب الجهوي",url:""},
    {t:"اجتماع المجلس الجهوي لجهة الدار البيضاء سطات",d:"انعقد يوم السبت 31 أكتوبر 2026 اجتماع المجلس الجهوي بحضور جميع ممثلي الأقاليم، لتدارس القضايا النقابية والمهنية بالجهة وتعزيز العمل التنظيمي والترافعي. الصور في قسم «الأنشطة».",c:"أنشطة",date:"2026-10-31",r:"الدار البيضاء سطات",src:"المكتب الجهوي",url:""},
    {t:"رسالة مفتوحة عاجلة إلى وزير الصحة والحماية الاجتماعية",d:"في إطار تتبع تنزيل اتفاق 23 يوليوز 2024، ينبه المكتب الوطني إلى ضرورة الحفاظ على صرف أجور موظفي قطاع الصحة من الميزانية العامة للدولة، في أفق تعديل القانون 08.22 المنظم للمجموعات الصحية الترابية (المادتان 16 و17)، ويؤكد أن مركزية المناصب المالية على رأس أولويات النقابة، منتظراً تفاعلاً إيجابياً أثناء إعداد مشروع قانون مالية 2027. نسخة إلى رئيسة الحكومة ووزير الاقتصاد والمالية.",c:"مراسلة",date:"2026-10-23",r:"الرباط",src:"المكتب الوطني",url:""},
    {t:"بيان احتجاجي حول طلب العروض 44/2026 للوكالة المغربية للدم ومشتقاته وإقصاء محضّري الصيدلة",d:"يرفض المكتب الوطني إسناد مهام صحية ومخبرية مرتبطة بالمتبرعين والمرضى إلى مستخدمي شركات المناولة (المادة 32 من دفتر التحملات)، وينبّه إلى إقصاء محضّري الصيدلة الخريجين المعطلين من مباراة الوكالة المغربية للأدوية والمنتجات الصحية لتوظيف 18 تقنياً تخصص الكيمياء، مطالباً بتوضيحات رسمية وحوار مؤسساتي عاجل. «الاختصاص المهني ليس مجالاً للاجتهاد خارج القانون، وسلامة المتبرعين والمرضى فوق كل اعتبار.»",c:"بيان احتجاجي",date:"2026-10-15",r:"الرباط",src:"المكتب الوطني",url:""},
    {t:"بلاغ بخصوص اختبار الأهلية لولوج المعاهد العليا للمهن التمريضية وتقنيات الصحة",d:"يعتبر مكتب التنسيق الوطني لأطر وأساتذة المعاهد العليا أن اختبار الأهلية المزمع تنظيمه من 15 إلى 18 شتنبر 2026، بصيغته الحالية، إجراء إداري فاقد للشرعية البيداغوجية لا يمنح الأستاذ أي سلطة تقييم فعلية. ويطالب الوزارة بتوضيح إطاره القانوني والتنظيمي وتركيبة اللجنة المشرفة، وتحديد نسب مكونات المباراة ومعايير الإقصاء، وإلا فإنه يدعو إلى إلغائه وتعويضه بمعاينة طبية مختصة.",c:"المعاهد العليا",date:"2026-09-13",r:"وطني",src:"مكتب التنسيق الوطني لأطر وأساتذة المعاهد العليا",url:""},
    {t:"بلاغ إلى المعنيين بقطاع الصحة والحماية الاجتماعية: هذا ما ننتظره من الإصلاح",d:"يذكّر المكتب الوطني الحكومة ووزارة الصحة والأحزاب المتنافسة بأن الإصلاح الحقيقي هو الالتفات إلى جميع العاملين دون محاباة، وتوفير العلاج والدواء، وطمأنة الموظفين على مناصبهم المالية المركزية، ووضع قائمة بأعمال الممرضين وتقنيي الصحة مع الاستفادة من الأجر المتغير، والتنصيص على الهيئة الوطنية، وتنزيل اتفاق يوليوز 2024. ويتساءل عن حرمان المدمجين في المجموعات الصحية الترابية ووكالة الدم من حق الإلحاق. «النقابة المستقلة تحاور بالتي هي أحسن، وتحتج بالتي هي أخشن، وكلاهما نضال.»",c:"مواقف",date:"2026-09-08",r:"الرباط",src:"المكتب الوطني",url:""},
    {t:"أول خروج إعلامي للكاتب الوطني للنقابة على منصة شعاع",d:"حوار مع السيد عبد الله ميروش، الكاتب الوطني للنقابة المستقلة للممرضين وتقنيي الصحة، في أول ظهور إعلامي له على منصة شعاع.",c:"إعلام",date:"2026-08-21",r:"وطني",src:"منصة شعاع",video:"https://youtu.be/vPHc9pv1c6Y"},
    {t:"النقابة المستقلة للممرضين تجدد القيادة في مؤتمرها الوطني الثاني",d:"بمشاركة نحو ألف مؤتمر ومؤتمرة، انتُخب عبد الله ميروش كاتباً وطنياً، ورضى تالوستن رئيساً للمجلس الوطني، ويوسف جمالي العلوي رئيساً لهيئة التحكيم والأخلاقيات، مع المصادقة على تعديلات القانون الأساسي.",c:"تنظيم",date:"2026-07-01",r:"وطني",src:"هسبريس",url:"https://www.hespress.com/%D8%A7%D9%84%D9%86%D9%82%D8%A7%D8%A8%D8%A9-%D8%A7%D9%84%D9%85%D8%B3%D8%AA%D9%82%D9%84%D8%A9-%D9%84%D9%84%D9%85%D9%85%D8%B1%D8%B6%D9%8A%D9%86-%D8%AA%D8%AC%D8%AF%D8%AF-%D8%A7%D9%84%D9%82%D9%8A%D8%A7-1770516.html"},
    {t:"البلاغ الختامي للمؤتمر الوطني الثاني",d:"انعقد المؤتمر يوم 27 يونيو 2026 دورة الفقيد المناضل عبد الإله الشاكي، بحضور قرابة 1000 مؤتمر ومؤتمرة. انتُخب المكتب الوطني الجديد بقيادة عبد الله ميروش، والكتاب الجهويون وممثلو الجهات الاثنتي عشرة.",c:"تنظيم",date:"2026-06-30",r:"الدار البيضاء",src:"رئاسة المؤتمر",url:""}
  ];
