  SIITS.PATH=[
    {y:"نونبر 2020",t:"التأسيس",d:"تأسيس النقابة المستقلة للممرضين وتقنيي الصحة كنقابة مهنية مفتوحة لعموم الممرضين وتقنيي الصحة."},
    {y:"2021",t:"الأولى في انتخابات اللجان الإدارية الثنائية",d:"تصدّرت النقابة المستقلة نتائج انتخابات اللجان الإدارية الثنائية لفئة الممرضين وتقنيي الصحة بـ70 مقعداً ونسبة 26.61%، متقدمةً على جميع النقابات الأخرى.",img:"elec2021",fit:true},
    {y:"11 يونيو 2024",t:"عضو مؤسس في الجبهة المغربية ضد قانوني الإضراب والتقاعد",d:"شاركت النقابة المستقلة في اللقاء التشاوري المؤسس للجبهة بالرباط، إلى جانب هيئات نقابية وطنية، رفضاً لتمرير قانوني الإضراب والتقاعد بصيغتيهما التراجعية ودفاعاً عن الحق في الإضراب وعن تقاعد لائق."},
    {y:"2024 – 2025",t:"محطات نضالية مع الجبهة المغربية ضد قانوني الإضراب والتقاعد",d:"شاركت النقابة في برنامج الجبهة النضالي: ثلاث وقفات وطنية أمام البرلمان، وأشكال احتجاجية جهوية يوم 1 دجنبر 2024، وأربع ندوات إعلامية، وملتقيان وطنيان (الأول عن بعد والثاني حضوري)، ومسيرة وطنية انطلاقاً من باب الأحد قوبلت بالمنع والقمع، ثم المشاركة مع الجبهة الثانية في مسيرة يناير 2025."},
    {y:"27 يونيو 2026",t:"المؤتمر الوطني الثاني: دورة الفقيد المناضل عبد الإله الشاكي",d:"بالدار البيضاء وبحضور قرابة 1000 مؤتمر ومؤتمرة. صودق بالإجماع على التقريرين الأدبي والمالي، وعلى تعديلات القانون الأساسي مادة بمادة، وانتُخب عبد الله ميروش كاتباً وطنياً.",img:"c1"},
    {y:"30 يونيو 2026",t:"البلاغ الختامي للمؤتمر",d:"دعوة المكتب الوطني الجديد لعقد أول اجتماع في أجل شهر، وإعداد أرضية لترتيب أولويات الملف الترافعي، وعقد مؤتمر جهوي استثنائي بدرعة تافيلالت في غضون ثلاثة أشهر."}
  ];
  SIITS.ACTS=[
    {t:"المؤتمر الإقليمي بسيدي سليمان: انتخاب منصف لمريبط كاتباً إقليمياً",date:"2026-10-31",place:"سيدي سليمان",type:"تنظيمي",d:"بتأطير من المكتب الوطني والمكتب الجهوي، وبحضور الكاتب الجهوي مصطفى زروال، وعضو المكتب الجهوي كدي المهدي، وممثل المكتب الوطني عبد الرزاق الفقير، انتُخب بالإجماع السيد منصف لمريبط كاتباً إقليمياً للنقابة بإقليم سيدي سليمان. ضم المكتب وجوهاً جديدة، وتدارس المؤتمر الذي دام أزيد من أربع ساعات مشاكل الإقليم، مع التشديد على الترافع من أجل إصلاح القطاع.",img:["act3","act2"]},
    {t:"اجتماع المجلس الجهوي لجهة الدار البيضاء سطات",date:"2026-10-31",place:"الدار البيضاء",type:"تنظيمي",d:"في إطار الدينامية التنظيمية للمكتب الجهوي، انعقد اجتماع المجلس الجهوي بحضور جميع ممثلي الأقاليم، لتدارس القضايا النقابية والمهنية بالجهة، وتوحيد الرؤى، ومناقشة سبل تعزيز العمل التنظيمي والترافعي بما يستجيب لتطلعات الشغيلة التمريضية وتقنيي الصحة.",img:["act0","act1"]},
    {t:"المؤتمر الوطني الثاني: دورة الفقيد المناضل عبد الإله الشاكي",date:"2026-06-27",place:"الدار البيضاء",type:"المؤتمر الوطني",d:"قرابة 1000 مؤتمر ومؤتمرة من مختلف جهات المملكة. صادق المؤتمر على التقريرين الأدبي والمالي وعلى تعديلات القانون الأساسي، وانتخب الأجهزة الوطنية الجديدة.",img:["c1","c2","c3","c4","c5"]}
  ];
